success.assertion:
for(const [fraction,expected]of[[0,1000],[.5,500],[.599,401],[.6,400],[.8,200],[.801,199],[1,0]]){const s=make({soul:true,move:29251,index:-1,hp:1000});if(fraction<=.5)timer(s,1,'固定百分比减伤',{fraction});let before;observe((e,c)=>{if(e==='beforeIncomingDamage'&&c.a.side===1&&fraction>.5)c.amount=expected;if(e==='roundEnd'&&c.a.side===0)before=c.a.hp;},()=>turn(s),true);const st=s.fighters[0].soulState.spacetime2050.intersections.at(-1);assert.equal(st.settledDamage,expected);assert.equal(st.firstTheoreticalHeal,1000);assert.equal(st.firstRestored,1000);assert.equal(st.branch,expected>400?'second-damage':expected<200?'prevent-switch':'next-round-reduction');assert.equal(s.fighters[0].hp,before+(expected>400?0:1000));if(expected>=200&&expected<=400){assert.equal(s.fighters[0].effects['额外攻击减伤'].start,2);assert.equal(s.fighters[0].effects['额外攻击减伤'].end,2);}}
const low=make({soul:true,move:29251,index:-1,targetHp:200});observe((e,c)=>{if(e==='combatEnd'&&c.a.side===0)c.a.hp=1000;},()=>turn(low));const st=low.fighters[0].soulState.spacetime2050.intersections.at(-1);assert.equal(st.settledDamage,1000);assert.equal(st.hpLoss,200);assert.equal(st.firstRestored,1000);assert.equal(low.fighters[1].hp,0);assert.equal(st.branch,'second-damage');
for(const mode of['enemy-immune','self-immune','global-heal-block','skill-heal-block']){const s=make({soul:true,move:29251,index:-1,hp:1000});if(mode==='enemy-immune')timer(s,1,'固定百分比免疫');if(mode==='self-immune')timer(s,0,'固定百分比免疫');if(mode==='global-heal-block')timer(s,0,'回复效果削减',{fraction:1});if(mode==='skill-heal-block')timer(s,0,'技能禁疗');turn(s);const x=s.fighters[0].soulState.spacetime2050.intersections.at(-1);assert.equal(x.firstRestored,mode==='global-heal-block'?0:1000);if(mode==='enemy-immune'){assert.equal(x.settledDamage,0);assert.equal(x.branch,'prevent-switch');}if(mode==='self-immune'){assert.equal(x.secondSettledDamage,0);assert.equal(x.secondTheoreticalHeal,1000);assert.equal(x.secondRestored,1000);}}

